def szukaj(wezel, cel):
    if wezel is None:
        return None
    if cel == wezel.wartosc:
        return wezel
    if cel < wezel.wartosc:
        return szukaj(wezel.lewy, cel)    # odrzucamy CAŁE prawe poddrzewo
    return szukaj(wezel.prawy, cel)       # odrzucamy CAŁE lewe poddrzewo
